"use client";

import { animate, useReducedMotion, type Transition } from "motion/react";
import {
  type ComponentPropsWithoutRef,
  type PointerEvent,
  type ReactNode,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

/** Props for a pull-to-refresh area. It is the scroller itself, so give it a height and put the list inside. */
export type PullToRefreshProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  children: ReactNode;
  /** Reloads the content. The indicator spins until the promise settles. */
  onRefresh: () => void | Promise<void>;
  /** How far the content must travel after resistance, in CSS pixels, before a release refreshes. */
  threshold?: number;
  /** Names the refresh button that keyboard and screen reader users reach instead of the pull. */
  refreshLabel?: string;
};

type Phase = "idle" | "pulling" | "armed" | "refreshing";

// Damping 39 is 2 × √380, rounded up: critically damped, so the content settles without bouncing.
const SETTLE: Transition = { type: "spring", stiffness: 380, damping: 39, mass: 1 };
const FOLLOW: Transition = { duration: 0 };
// A small move is still a tap or a click. The pull starts past this distance.
const SLOP = 6;

// The pull gets heavier the further it goes, and never passes twice the threshold.
function resist(distance: number, threshold: number) {
  const limit = threshold * 2;
  return limit * (1 - Math.exp(-Math.max(0, distance) / limit));
}

function ArcGlyph({ spinning }: { spinning: boolean }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      aria-hidden="true"
      className={cn("size-6", spinning && "motion-safe:animate-spin")}
    >
      <circle cx="12" cy="12" r="8.5" className="opacity-20" />
      <path d="M12 3.5a8.5 8.5 0 0 1 8.5 8.5" strokeLinecap="round" />
    </svg>
  );
}

/**
 * A scrolling area that reloads when the person pulls it down from the top and
 * lets go past a threshold. The pull resists, the indicator turns with it, and
 * the content waits a little lower until the refresh finishes.
 */
export function PullToRefresh({
  children,
  onRefresh,
  threshold = 64,
  refreshLabel = "Refresh",
  className,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
  ...divProps
}: PullToRefreshProps) {
  const [phase, setPhase] = useState<Phase>("idle");
  const [outcome, setOutcome] = useState<"none" | "refreshed" | "failed">("none");
  const scrollerRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const indicatorRef = useRef<HTMLDivElement>(null);
  // The gesture changes on every frame of a drag, so it lives in a ref and the
  // offset reaches the page through Motion, never through a React render.
  const gesture = useRef<{ startY: number; startX: number; pulling: boolean } | null>(null);
  const phaseRef = useRef<Phase>("idle");
  const reduceMotion = useReducedMotion();

  const changePhase = (next: Phase) => {
    phaseRef.current = next;
    setPhase(next);
  };

  const paint = (y: number, transition: Transition) => {
    const progress = Math.min(1, y / threshold);
    if (contentRef.current) animate(contentRef.current, { y }, transition);
    if (indicatorRef.current) {
      animate(indicatorRef.current, reduceMotion ? { opacity: progress } : { opacity: progress, rotate: progress * 270 }, transition);
    }
  };

  const settle = (y: number) => paint(y, reduceMotion ? FOLLOW : SETTLE);

  const refresh = async () => {
    if (phaseRef.current === "refreshing") return;
    changePhase("refreshing");
    settle(threshold);
    try {
      await onRefresh();
      setOutcome("refreshed");
    } catch {
      setOutcome("failed");
    } finally {
      changePhase("idle");
      settle(0);
    }
  };

  const begin = (x: number, y: number) => {
    const atTop = (scrollerRef.current?.scrollTop ?? 0) <= 0;
    gesture.current = atTop && phaseRef.current === "idle" ? { startX: x, startY: y, pulling: false } : null;
  };

  // Returns true while this gesture is a pull, so the caller can stop the page scrolling.
  const move = (x: number, y: number) => {
    const current = gesture.current;
    if (!current) return false;
    const dy = y - current.startY;
    const dx = x - current.startX;
    if (!current.pulling) {
      // Upward or sideways movement is a scroll or a swipe, so the pull lets it go.
      if (dy < SLOP || Math.abs(dx) > dy) {
        if (dy < 0 || Math.abs(dx) > SLOP) gesture.current = null;
        return false;
      }
      current.pulling = true;
      // A mouse press has already started a text selection by now. The pull owns the drag, so clear it.
      window.getSelection()?.removeAllRanges();
    }
    const pulled = resist(dy - SLOP, threshold);
    paint(pulled, FOLLOW);
    changePhase(pulled >= threshold ? "armed" : "pulling");
    return true;
  };

  const release = () => {
    const wasPulling = gesture.current?.pulling;
    gesture.current = null;
    if (!wasPulling) return;
    if (phaseRef.current === "armed") {
      void refresh();
      return;
    }
    changePhase("idle");
    settle(0);
  };

  // A finger needs native listeners: only a non-passive touchmove can stop the
  // page scrolling, and React attaches touch handlers as passive. The listeners
  // read the latest handlers through this ref, so they attach once.
  const touchHandlers = useRef({ begin, move, release });
  useLayoutEffect(() => {
    touchHandlers.current = { begin, move, release };
  });
  useEffect(() => {
    const scroller = scrollerRef.current;
    if (!scroller) return;
    const onStart = (event: TouchEvent) => {
      const touch = event.touches[0];
      if (event.touches.length === 1 && touch) touchHandlers.current.begin(touch.clientX, touch.clientY);
    };
    const onMove = (event: TouchEvent) => {
      const touch = event.touches[0];
      if (touch && touchHandlers.current.move(touch.clientX, touch.clientY)) event.preventDefault();
    };
    const onEnd = () => touchHandlers.current.release();
    scroller.addEventListener("touchstart", onStart, { passive: true });
    scroller.addEventListener("touchmove", onMove, { passive: false });
    scroller.addEventListener("touchend", onEnd);
    scroller.addEventListener("touchcancel", onEnd);
    return () => {
      scroller.removeEventListener("touchstart", onStart);
      scroller.removeEventListener("touchmove", onMove);
      scroller.removeEventListener("touchend", onEnd);
      scroller.removeEventListener("touchcancel", onEnd);
    };
  }, []);

  // A mouse or a pen pulls through pointer events. Capture starts only once the
  // pull does, so a plain click still reaches the button under it.
  const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
    onPointerDown?.(event);
    if (event.defaultPrevented || event.pointerType === "touch" || event.button !== 0) return;
    begin(event.clientX, event.clientY);
  };

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    onPointerMove?.(event);
    if (event.pointerType === "touch") return;
    // The button came up outside the area, where this element never heard it.
    if (event.buttons === 0) {
      release();
      return;
    }
    if (!move(event.clientX, event.clientY)) return;
    event.currentTarget.setPointerCapture(event.pointerId);
  };

  const handlePointerEnd = (event: PointerEvent<HTMLDivElement>) => {
    if (event.type === "pointerup") onPointerUp?.(event);
    else onPointerCancel?.(event);
    if (event.pointerType !== "touch") release();
  };

  const pulling = phase === "pulling" || phase === "armed";
  const statusText =
    phase === "refreshing" ? "Refreshing" : outcome === "refreshed" ? "Refreshed" : outcome === "failed" ? "Refresh failed" : "";

  return (
    <div
      {...divProps}
      ref={scrollerRef}
      data-phase={phase}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerEnd}
      onPointerCancel={handlePointerEnd}
      className={cn(
        "relative overflow-y-auto overscroll-contain",
        pulling && "cursor-grabbing select-none",
        className,
      )}
    >
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-0 top-0 flex h-16 items-center justify-center text-muted-foreground"
      >
        <div ref={indicatorRef} className="flex opacity-0">
          <ArcGlyph spinning={phase === "refreshing"} />
        </div>
      </div>
      {/* The pull is a gesture, so keyboard and screen reader users get a button that does the same. It shows while focused. */}
      <div className="absolute inset-x-0 top-2 z-20 flex justify-center">
        <button
          type="button"
          onClick={() => void refresh()}
          // Not disabled while it runs: a disabled button drops focus and the button would vanish.
          aria-disabled={phase === "refreshing" || undefined}
          className="sr-only rounded-full border border-border bg-background px-4 py-2 text-sm font-medium text-foreground outline-none focus:not-sr-only focus-visible:ring-2 focus-visible:ring-ring"
        >
          {refreshLabel}
        </button>
      </div>
      <div ref={contentRef} aria-busy={phase === "refreshing"} className="relative">
        {children}
      </div>
      <span role="status" className="sr-only">
        {statusText}
      </span>
    </div>
  );
}
